import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useTheme } from '../../context/ThemeContext';
import { useLanguageContext } from '../../context/LanguageContext';
import { useNews } from '../../context/NewsContext';
import './NewsSlider.css';

const NewsSlider = () => {
  const { colors, isDarkMode } = useTheme();
  const { t, language } = useLanguageContext();
  const { news } = useNews();
  
  const [activeIndex, setActiveIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);

  const activeNews = news.length > 0 ? news : [];

  useEffect(() => {
    if (isPaused || activeNews.length === 0) return;
    const interval = setInterval(() => {
      setActiveIndex((prev) => (prev + 1) % activeNews.length);
    }, 5000);
    return () => clearInterval(interval);
  }, [isPaused, activeNews.length]);

  const categoryIcons = {
    general: '📋', tournament: '🏆', update: '🔄', event: '🎉', team: '👥',
  };

  const categoryColors = {
    general: '#2196F3', tournament: '#FF9800', update: '#4CAF50', event: '#9C27B0', team: '#E91E63',
  };

  const categoryLabels = {
    fa: { general: 'عمومی', tournament: 'تورنمنت', update: 'بروزرسانی', event: 'رویداد', team: 'تیم' },
    en: { general: 'General', tournament: 'Tournament', update: 'Update', event: 'Event', team: 'Team' },
  };

  if (activeNews.length === 0) {
    return (
      <div className="space-slider-wrapper">
        <div className="container" style={{ textAlign: 'center', padding: '60px 0' }}>
          <motion.div
            animate={{ scale: [1, 1.1, 1], rotate: [0, 10, -10, 0] }}
            transition={{ duration: 2, repeat: Infinity }}
            style={{ fontSize: '5rem', marginBottom: '20px' }}
          >
            🛸
          </motion.div>
          <h3 style={{ color: colors.text }}>
            {language === 'fa' ? 'خبری موجود نیست' : 'No News Available'}
          </h3>
        </div>
      </div>
    );
  }

  // نمایش حداکثر ۶ خبر روی مدار
  const displayNews = activeNews.slice(0, 6);
  const radius = 220; // شعاع مدار

  return (
    <div className="space-slider-wrapper" onMouseEnter={() => setIsPaused(true)} onMouseLeave={() => setIsPaused(false)}>
      <div className="container">
        {/* تایتل */}
        <motion.h2
          initial={{ opacity: 0, y: -20 }}
          whileInView={{ opacity: 1, y: 0 }}
          className="gradient-text"
          style={{
            textAlign: 'center',
            fontSize: 'clamp(1.5rem, 3vw, 2rem)',
            fontWeight: 800,
            marginBottom: '10px',
          }}
        >
          {t('home.newsTitle')}
        </motion.h2>

        {/* سیستم خورشیدی */}
        <div className="solar-system">
          {/* مدارها */}
          {[0.6, 0.8, 1].map((scale, i) => (
            <div
              key={i}
              className="orbit-ring"
              style={{
                width: `${radius * 2 * scale}px`,
                height: `${radius * 2 * scale}px`,
                borderColor: `${displayNews[activeIndex] ? (categoryColors[displayNews[activeIndex]?.category] || '#2196F3') : '#2196F3'}15`,
                animationDuration: `${15 + i * 8}s`,
                animationDirection: i % 2 === 0 ? 'normal' : 'reverse',
              }}
            />
          ))}

          {/* خورشید مرکزی - DarkLight */}
          <motion.div
            className="sun-core"
            animate={{
              boxShadow: [
                `0 0 40px ${colors.accent}40, 0 0 80px ${colors.accent}20`,
                `0 0 60px ${colors.accent}60, 0 0 120px ${colors.accent}30`,
                `0 0 40px ${colors.accent}40, 0 0 80px ${colors.accent}20`,
              ],
            }}
            transition={{ duration: 2, repeat: Infinity }}
            style={{
              width: '100px',
              height: '100px',
              borderRadius: '50%',
              background: `radial-gradient(circle, ${colors.accent}, ${colors.accent}88, transparent)`,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              zIndex: 10,
              cursor: 'pointer',
            }}
            onClick={() => setActiveIndex((prev) => (prev + 1) % displayNews.length)}
          >
            <span style={{
              color: '#fff',
              fontWeight: 900,
              fontSize: '0.9rem',
              textShadow: '0 0 10px rgba(0,0,0,0.5)',
              textAlign: 'center',
              lineHeight: 1.1,
            }}>
              Dark<br/>Light
            </span>
          </motion.div>

          {/* سیاره‌های خبری */}
          {displayNews.map((item, index) => {
            const angle = (index / displayNews.length) * 360;
            const radian = (angle * Math.PI) / 180;
            const x = Math.cos(radian) * radius;
            const y = Math.sin(radian) * radius;
            const catColor = categoryColors[item?.category] || '#2196F3';
            const isActive = index === activeIndex;

            return (
              <motion.div
                key={item.id}
                className={`news-planet ${isActive ? 'news-planet--active' : ''}`}
                animate={{
                  x: x,
                  y: y,
                  scale: isActive ? 1.3 : 0.85,
                  zIndex: isActive ? 20 : 5,
                }}
                transition={{
                  type: 'spring',
                  stiffness: 100,
                  damping: 20,
                }}
                onClick={() => setActiveIndex(index)}
                style={{
                  position: 'absolute',
                  width: isActive ? '90px' : '65px',
                  height: isActive ? '90px' : '65px',
                  borderRadius: '50%',
                  background: `radial-gradient(circle at 30% 30%, ${catColor}, ${catColor}88, ${isDarkMode ? '#1e293b' : '#f0f4ff'})`,
                  border: `2px solid ${catColor}60`,
                  cursor: 'pointer',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  justifyContent: 'center',
                  textAlign: 'center',
                  boxShadow: isActive ? `0 0 30px ${catColor}60, 0 0 60px ${catColor}30` : `0 0 10px ${catColor}20`,
                  overflow: 'hidden',
                }}
              >
                {/* حلقه دور سیاره فعال */}
                {isActive && (
                  <div
                    style={{
                      position: 'absolute',
                      top: '-4px', left: '-4px', right: '-4px', bottom: '-4px',
                      borderRadius: '50%',
                      border: `1.5px solid ${catColor}50`,
                      animation: 'ring-spin 4s linear infinite',
                    }}
                  />
                )}

                <span style={{ fontSize: isActive ? '1.4rem' : '1rem', zIndex: 1 }}>
                  {categoryIcons[item?.category] || '📋'}
                </span>
                
                {isActive && (
                  <motion.span
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    style={{
                      fontSize: '0.5rem',
                      color: '#fff',
                      fontWeight: 600,
                      textShadow: '0 0 5px rgba(0,0,0,0.5)',
                      zIndex: 1,
                      maxWidth: '70px',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                      marginTop: '2px',
                    }}
                  >
                    {language === 'fa' ? item.title : (item.titleEn || item.title)}
                  </motion.span>
                )}
              </motion.div>
            );
          })}

          {/* ذرات ستاره‌ای */}
          {[...Array(20)].map((_, i) => (
            <motion.div
              key={`star-${i}`}
              animate={{
                opacity: [0.2, 0.8, 0.2],
                scale: [0.8, 1.2, 0.8],
              }}
              transition={{
                duration: 2 + Math.random() * 3,
                repeat: Infinity,
                delay: Math.random() * 2,
              }}
              style={{
                position: 'absolute',
                width: `${Math.random() * 3 + 1}px`,
                height: `${Math.random() * 3 + 1}px`,
                borderRadius: '50%',
                background: '#fff',
                top: `${Math.random() * 100}%`,
                left: `${Math.random() * 100}%`,
                opacity: 0.5,
              }}
            />
          ))}
        </div>

        {/* اطلاعات سیاره فعال */}
        <AnimatePresence mode="wait">
          <motion.div
            key={activeIndex}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ duration: 0.3 }}
            className="planet-info glass"
            style={{
              background: `${colors.card}ee`,
              border: `1px solid ${colors.border}`,
              borderRadius: '20px',
              padding: '20px 25px',
              maxWidth: '450px',
              margin: '20px auto 0',
              textAlign: 'center',
              backdropFilter: 'blur(20px)',
            }}
          >
            <span style={{
              padding: '4px 12px',
              background: `${(categoryColors[displayNews[activeIndex]?.category] || '#2196F3')}20`,
              color: categoryColors[displayNews[activeIndex]?.category] || '#2196F3',
              borderRadius: '15px',
              fontSize: '0.75rem',
              fontWeight: 600,
            }}>
              {categoryLabels[language]?.[displayNews[activeIndex]?.category] || displayNews[activeIndex]?.category}
            </span>
            
            <h4 style={{ color: colors.text, margin: '10px 0 5px', fontSize: '1rem', fontWeight: 700 }}>
              {language === 'fa' 
                ? displayNews[activeIndex]?.title 
                : (displayNews[activeIndex]?.titleEn || displayNews[activeIndex]?.title)}
            </h4>
            
            <p style={{ color: colors.textSecondary, fontSize: '0.85rem', margin: '5px 0', lineHeight: 1.5 }}>
              {language === 'fa'
                ? displayNews[activeIndex]?.content?.substring(0, 100) + '...'
                : (displayNews[activeIndex]?.contentEn || displayNews[activeIndex]?.content)?.substring(0, 100) + '...'}
            </p>
            
            <span style={{ color: colors.textSecondary, fontSize: '0.7rem' }}>
              🕐 {displayNews[activeIndex]?.date}
            </span>
          </motion.div>
        </AnimatePresence>

        {/* دات‌های نویگیشن */}
        <div style={{ display: 'flex', justifyContent: 'center', gap: '8px', marginTop: '15px' }}>
          {displayNews.map((_, i) => (
            <motion.button
              key={i}
              whileHover={{ scale: 1.3 }}
              whileTap={{ scale: 0.9 }}
              onClick={() => setActiveIndex(i)}
              style={{
                width: i === activeIndex ? '24px' : '8px',
                height: '8px',
                borderRadius: '4px',
                border: 'none',
                background: i === activeIndex ? colors.accent : `${colors.textSecondary}40`,
                cursor: 'pointer',
                transition: 'all 0.3s ease',
              }}
            />
          ))}
        </div>
      </div>

      <style>{`
        @keyframes ring-spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default NewsSlider;
